SELECT 
FROM flow_instance i
WHERE 1 = 1
  AND /* @dataScope(table=flow_instance, alias=i) */

  AND i.template_id = #{templateId}


  AND i.template_version = #{templateVersion}


  AND i.status = #{status}


  AND i.initiator_id = #{initiatorId}

ORDER BY i.id DESC

  LIMIT #{limit}

SELECT i.id AS instance_id, i.biz_no, i.template_id, i.template_version, i.status, i.sub_status, i.initiator_id, u.name AS initiator_name, i.current_node_seq, (SELECT n2.node_name FROM flow_node_instance n2 WHERE n2.instance_id = i.id AND n2.node_seq = i.current_node_seq ORDER BY n2.id ASC LIMIT 1) AS current_node_name, DATE_FORMAT(IFNULL(i.submitted_at, i.created_at), '%Y-%m-%d %H:%i:%s') AS submitted_at FROM flow_instance i LEFT JOIN sys_user u ON u.id = i.initiator_id WHERE 1 = 1 AND /* @dataScope(table=flow_instance, alias=i) */ AND i.template_id = #{templateId} AND i.status = 'approving'
AND i.template_version = #{templateVersion}
ORDER BY i.id DESC

mapper.update:
UPDATE flow_instance
SET current_node_seq = #{currentNodeSeq}, updated_at = NOW()
WHERE id = #{id}
